  if (firstType === "staff") return 93;
  if (firstType === "potion") return 49;
  if (firstType === "rune") return 33;
  // Only the sword example reaches here; no active test constrains any other case.
  return 115;
};

const runStep = (step: Step): StepResult => {
  if (step.op === "quote") return { premium: quotePremium(step.items) };
